#!/bin/bash
x86_64-linux-gnu-gcc -ffreestanding -fno-stack-protector -fno-pic -fno-pie -mno-red-zone -mno-sse -mno-sse2 -mcmodel=kernel -nostdlib -O2 -DDEF_WEAK\(x\)= -D__KERNEL_RCSID\(x,y\)= -D__CTASSERT\(x\)= -D__CTASSERT0\(x,y,z\)= -D__NetBSD__ -D_KERNEL -D_NETBSD_SOURCE -I/mnt/e/lh/lsr/Ainux/custom_kernel/src/c -I/mnt/e/lh/lsr/Ainux/custom_kernel/src/c/libc -I/mnt/e/lh/lsr/Ainux/custom_kernel/src/c/include -I/mnt/e/lh/lsr/Ainux/custom_kernel/src/bsd_compat/include -I/mnt/e/lh/lsr/Ainux/custom_kernel/external/netbsd-src/sys -c /mnt/e/lh/lsr/Ainux/custom_kernel/external/netbsd-src/sys/net/if.c -o /dev/null
